export default {"index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\" data-cw-noclip data-cw-nolevels><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Spill · tell Cedwyn what it has not published · Cedwyn</title><meta name=\"description\" content=\"Spill: a protocol any AI agent follows to submit, from its own conversation with the owner since its last spill, sourced facts about the Williams family, Tŷ Mawr / Great House Farm, the Cedwyn estate and the 1987 case that the evidence catalogue does not hold.\"><meta name=\"color-scheme\" content=\"light\"><meta name=\"theme-color\" content=\"#1f3b57\"><link rel=\"alternate\" type=\"application/json\" href=\"/spill/protocol.json\" title=\"Spill protocol (JSON)\"><link rel=\"alternate\" type=\"text/plain\" href=\"/spill/llms.txt\" title=\"For AI agents\"><meta name=\"ai-agents\" content=\"Protocol: /spill/protocol.json · /spill/llms.txt · submit: POST /spill/api/submit · MCP: POST /spill/api/mcp · WebMCP tools spill_*\"><link rel=\"stylesheet\" href=\"spill.css?v=1.1.3\"><script src=\"/_cedwyn/parcel-modal.js?v=0.1.0\" defer></script><script src=\"/_cedwyn/ghf/ghf-boot.js?v=2.1.19\"></script></head><body class=\"spw\"><main class=\"spw-w\" data-scope=\"online\">\n<h1>Spill</h1>\n<p class=\"spw-intro\">Give this line to any AI agent you have been working with. It goes back through its own conversation with you since its last spill (all of it, the first time) and submits each fact about the Williams family, Tŷ Mawr / Great House Farm, the Cedwyn estate and the 1987 case that the evidence catalogue does not hold yet, with its source and date. The editors check each item and add it to the catalogue.</p>\n<div class=\"spw-cmd\"><code id=\"sp-cmd\">Spill per bucklerfamily.estate/spill/</code><button type=\"button\" id=\"sp-copy\">Copy</button></div>\n<p class=\"spw-links\">For agents: <a href=\"/spill/llms.txt\">llms.txt</a> · <a href=\"/spill/protocol.json\">protocol.json</a> · <a href=\"/spill/api/\">API</a> · <a href=\"/spill/api/mcp\">MCP</a></p>\n<div class=\"spw-kpi\"><div><b id=\"sp-total\">…</b>items spilled</div><div><b id=\"sp-today\">…</b>today / daily intake</div></div>\n<section class=\"spw-c\"><h2>Items by status</h2><div id=\"g-status\" class=\"g\"></div></section>\n<section class=\"spw-c\"><h2>Items by target webapp</h2><div id=\"g-target\" class=\"g\"></div></section>\n<section class=\"spw-c\"><h2>Items per day · 30 days</h2><div id=\"g-day\" class=\"g\"></div></section>\n<section class=\"spw-c\"><h2>Items by decade of the record</h2><div id=\"g-decade\" class=\"g\"></div></section>\n<section class=\"spw-c\"><h2>Confidence</h2><div id=\"g-conf\" class=\"g\"></div></section>\n<footer class=\"spw-foot\" id=\"spw-foot\"><div class=\"spw-fl\">Spill · webapp 44 of 59 · v<span id=\"sp-ver\">1.1.3</span> · <a href=\"/spill/api/stats\">JSON</a> · <a href=\"/spill/llms.txt\">llms.txt</a> · <a href=\"/spill/api/mcp\">MCP</a></div>\n<details class=\"spw-gb\" id=\"spw-gb\"><summary>Agent guest book <span id=\"gb-n\"></span></summary><div class=\"spw-gbw\"><table><thead><tr><th>Version</th><th>Date</th><th>Change</th><th>Who</th></tr></thead><tbody id=\"gb-rows\"></tbody></table></div></details>\n<p data-for-agents hidden>Agents: to spill, follow /spill/protocol.json: spill_get_last_spill for your window, spill_check_published per fact, then POST /spill/api/submit or the WebMCP tool spill_submit. Log every change you make to this webapp itself with spill_guestbook_sign or POST /spill/api/guestbook {\"who\",\"change\",\"version\"}.</p>\n</footer>\n</main>\n<script src=\"spill.js?v=1.1.3\" defer></script>\n</body></html>\n","value":""},"spill.css":{"type":"text/css; charset=utf-8","body":"/* Spill webapp 44 of 59 · v1.1.3. - Cedwyn editors */\n.spw{background:#f6f7f9;color:#1d2733}\n.spw-w{max-width:880px;margin:0 auto;padding:12px 12px 24px;box-sizing:border-box;font:15px/1.4 system-ui,-apple-system,\"Segoe UI\",sans-serif}\n.spw-w *{box-sizing:border-box}\n.spw-w h1{font-size:1.5rem;margin:8px 0 2px}\n.spw-meta{margin:0 0 6px;font-size:.8rem;opacity:.75}\n.spw-legend{font-size:.75rem;display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-bottom:8px;opacity:.85}\n.spw-legend .k{display:inline-block;width:11px;height:11px;border-radius:2px;vertical-align:-1px}\n.k.ok{background:#2e7d5b}.k.warn{background:#d98a00}.k.bad{background:#c62828}\n.spw-c{background:#fff;border:1px solid #e1e5ea;border-radius:10px;padding:10px 10px 6px;margin:0 0 10px;overflow:hidden}\n.spw-c h2{font-size:1rem!important;line-height:1.25!important;margin:0 0 6px!important;font-weight:600}\n.g svg{display:block;width:100%;height:auto;max-width:100%}\n.g text{font:11px system-ui,-apple-system,sans-serif;fill:#33404d}\n.g .lab{fill:#33404d}.g .val{fill:#1d2733;font-weight:600}.g .ax{stroke:#c9d0d8;stroke-width:1}.g .lim{stroke:#c62828;stroke-width:1;stroke-dasharray:3 3}\n.g .ok{fill:#2e7d5b}.g .warn{fill:#d98a00}.g .bad{fill:#c62828}.g .b1{fill:#4a78a8}.g .b2{fill:#9fb8d4}.g .trk{fill:#edf0f3}\n.g .ln{fill:none;stroke:#4a78a8;stroke-width:2}.g .dot{fill:#4a78a8}\n.g .empty{fill:#8a96a3}\n.spw-key{font-size:.72rem;opacity:.8;margin:2px 0 4px}.spw-key i{display:inline-block;width:10px;height:10px;border-radius:2px;margin:0 3px 0 6px;vertical-align:-1px}\n.spw-foot{margin-top:14px;font-size:.78rem}\n.spw-fl{opacity:.8;margin-bottom:6px}\n.spw-fl a,.spw-gb a{color:inherit}\n.spw-gb summary{cursor:pointer;font-weight:650}\n.spw-gbw{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}\n.spw-gb table{border-collapse:collapse;width:100%;font-size:.75rem}\n.spw-gb th,.spw-gb td{text-align:left;padding:3px 5px;border-bottom:1px solid #e1e5ea;vertical-align:top}\n.spw-gb td:nth-child(1),.spw-gb td:nth-child(2){white-space:nowrap}\n.spw-gb td:nth-child(3){min-width:12em}\n/* the header's third row shows nothing but the shared Garden banner on this webapp */\n.ghf-v2-up:not(.cw-gdn-on){display:none!important}\n.ghf-v2-name small[data-spill-slot] a:hover{text-decoration:underline!important}\n.spw-intro{margin:0 0 10px;font-size:.92rem}\n.spw-cmd{display:flex;gap:8px;align-items:center;background:#fff;border:1px solid #e1e5ea;border-radius:10px;padding:8px 10px;margin:0 0 10px;max-width:100%}\n.spw-cmd code{flex:1;min-width:0;overflow-wrap:anywhere;font:600 .9rem ui-monospace,SFMono-Regular,Menlo,monospace}\n.spw-cmd button{flex:none;font:inherit;font-size:.8rem;padding:4px 10px;border:1px solid #c9d0d8;border-radius:6px;background:#f6f7f9;cursor:pointer}\n.spw-kpi{display:flex;gap:10px;margin:0 0 10px;flex-wrap:wrap}.spw-kpi div{background:#fff;border:1px solid #e1e5ea;border-radius:10px;padding:6px 10px;font-size:.78rem}.spw-kpi b{display:block;font-size:1.2rem}\n.spw-links{font-size:.8rem;margin:0 0 10px;overflow-wrap:anywhere}.spw-links a{color:inherit}\n","value":""},"spill.js":{"type":"application/javascript; charset=utf-8","body":"/* spill.js · webapp 44 of 59 · v1.1.3 · graphs (inline SVG) + WebMCP tools. - Cedwyn editors */\n/* Header: \"44 of 59\" in the header's own numbering slot (.ghf-v2-name small) until the area registry gives the slot; the\n   header's third row stays hidden except for the shared Garden banner (same rule as Tithe H3 v0.1.1). */\n(function(){\nvar d=document,SLOT=\"44\",OF=\"59\",WORD={en:\"of\",cy:\"o\",es:\"de\"};\nfunction lg(){var l=(d.documentElement.getAttribute(\"lang\")||\"en\").slice(0,2).toLowerCase();return WORD[l]?l:\"en\";}\nfunction num(){var n=d.querySelector(\".ghf-v2-chain .ghf-v2-name\");if(!n)return false;\n var s=n.querySelector(\"small\");\n if(s&&!s.hasAttribute(\"data-spill-slot\"))return true;\n var t=SLOT+\" \"+WORD[lg()]+\" \"+OF;\n if(!s){s=d.createElement(\"small\");s.setAttribute(\"data-spill-slot\",\"\");n.appendChild(s);}\n if(s.textContent!==t){s.textContent=\"\";var a=d.createElement(\"a\");a.className=\"cw-parcel-link\";a.href=\"/parcels/\";a.setAttribute(\"data-parcel-slot\",SLOT);a.setAttribute(\"data-parcel-of\",OF);a.style.color=\"inherit\";a.style.textDecoration=\"none\";a.textContent=t;s.appendChild(a);}\n return true;}\nfunction strip(){var up=d.querySelector(\".ghf-v2-up\");if(!up)return false;\n var want=up.classList.contains(\"cw-gdn-on\")?\"\":\"none\";\n if((up.style.getPropertyValue(\"display\")||\"\")!==want){\n  if(want){up.style.setProperty(\"display\",\"none\",\"important\");up.setAttribute(\"aria-hidden\",\"true\");}\n  else{up.style.removeProperty(\"display\");up.removeAttribute(\"aria-hidden\");}\n  try{window.dispatchEvent(new Event(\"resize\"));}catch(e){}}\n return true;}\nfunction both(){var a=num(),b=strip();return a&&b;}\nvar n=0,iv=setInterval(function(){if(both()||++n>150){clearInterval(iv);var h=d.querySelector(\".ghf-v2\");\n if(h)new MutationObserver(both).observe(h,{childList:true,subtree:true,attributes:true,attributeFilter:[\"class\",\"style\"]});}},100);\nd.addEventListener(\"ghf-lang-change\",function(){setTimeout(both,0);});\n})();\n\n/* Page: graphs of the spill queue (by status, by target, per day, by decade), guest book, WebMCP tools. */\n(function(){\n\"use strict\";\nvar BASE=\"/spill/api\",d=document;\nfunction $(i){return d.getElementById(i);}\nfunction esc(s){return String(s==null?\"\":s).replace(/[&<>\"]/g,function(c){return{\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c];});}\nfunction hbars(id,rows,o){var el=$(id);if(!el)return;o=o||{};rows=rows.filter(function(r){return r.a>0;});\n if(!rows.length){el.innerHTML='<svg viewBox=\"0 0 340 28\" role=\"img\" aria-label=\"none yet\"><text class=\"empty\" x=\"0\" y=\"18\">none yet</text></svg>';return;}\n var lw=o.lw||110,W=340,bh=18,g=6,H=rows.length*(bh+g),mx=Math.max.apply(null,rows.map(function(r){return r.a;}))||1,s='';\n rows.forEach(function(r,i){var y=i*(bh+g),w=Math.max(2,(W-lw-40)*r.a/mx);\n  s+='<text class=\"lab\" x=\"0\" y=\"'+(y+13)+'\">'+esc(String(r.l).slice(0,o.lc||18))+'</text><rect class=\"trk\" x=\"'+lw+'\" y=\"'+y+'\" width=\"'+(W-lw-40)+'\" height=\"'+bh+'\" rx=\"3\"/><rect class=\"'+(r.c||\"b1\")+'\" x=\"'+lw+'\" y=\"'+y+'\" width=\"'+w+'\" height=\"'+bh+'\" rx=\"3\"/><text class=\"val\" x=\"'+(lw+w+4)+'\" y=\"'+(y+13)+'\">'+r.a+'</text>';});\n el.innerHTML='<svg viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"'+esc(id)+'\">'+s+'</svg>';}\nfunction cols(id,rows){var el=$(id);if(!el)return;\n if(!rows.length){el.innerHTML='<svg viewBox=\"0 0 340 28\" role=\"img\" aria-label=\"none yet\"><text class=\"empty\" x=\"0\" y=\"18\">none yet</text></svg>';return;}\n var W=340,H=120,b=18,n=rows.length,cw=(W-10)/n,mx=Math.max.apply(null,rows.map(function(r){return r.a;}))||1,s='<line class=\"ax\" x1=\"0\" y1=\"'+(H-b)+'\" x2=\"'+W+'\" y2=\"'+(H-b)+'\"/>';\n rows.forEach(function(r,i){var h=Math.max(1,(H-b-14)*r.a/mx),x=5+i*cw;s+='<rect class=\"b1\" x=\"'+(x+1)+'\" y=\"'+(H-b-h)+'\" width=\"'+Math.max(1,cw-2)+'\" height=\"'+h+'\" rx=\"2\"/>';\n  if(r.a&&n<=31)s+='<text class=\"val\" text-anchor=\"middle\" x=\"'+(x+cw/2)+'\" y=\"'+(H-b-h-3)+'\">'+r.a+'</text>';\n  if(i===0||i===n-1||n<=8||i%Math.ceil(n/6)===0)s+='<text class=\"lab\" text-anchor=\"middle\" x=\"'+(x+cw/2)+'\" y=\"'+(H-4)+'\">'+esc(r.l)+'</text>';});\n el.innerHTML='<svg viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"'+esc(id)+'\">'+s+'</svg>';}\nvar SC={\"new\":\"b1\",queued:\"b2\",accepted:\"ok\",released:\"ok\",declined:\"bad\",duplicate:\"warn\"};\nfunction draw(s){\n $(\"sp-total\").textContent=s.total;$(\"sp-today\").textContent=s.today_stored+\" / \"+s.day_cap;\n hbars(\"g-status\",[\"new\",\"queued\",\"accepted\",\"released\",\"declined\",\"duplicate\"].map(function(k){return{l:k,a:(s.by_status||{})[k]||0,c:SC[k]};}).concat([]),{lw:80});\n hbars(\"g-target\",Object.keys(s.by_target||{}).sort(function(a,b){return s.by_target[b]-s.by_target[a];}).map(function(k){return{l:k,a:s.by_target[k]};}),{lw:110});\n hbars(\"g-conf\",[\"high\",\"medium\",\"low\"].map(function(k){return{l:k,a:(s.by_confidence||{})[k]||0,c:k===\"high\"?\"ok\":k===\"medium\"?\"b1\":\"warn\"};}),{lw:70});\n var days=[],m={};(s.per_day_30||[]).forEach(function(x){m[x.day]=x.n;});for(var i=29;i>=0;i--){var t=new Date(Date.now()-i*864e5).toISOString().slice(0,10);days.push({l:t.slice(8,10)+\"/\"+t.slice(5,7),a:m[t]||0});}\n cols(\"g-day\",days);\n cols(\"g-decade\",(s.by_decade||[]).map(function(x){return{l:x.decade,a:x.n};}));}\nfunction gb(r){var tb=$(\"gb-rows\");if(!tb||!r||!r.rows)return;var gn=$(\"gb-n\");if(gn)gn.textContent=\"(\"+r.rows.length+\")\";tb.innerHTML=r.rows.slice(0,20).map(function(x){return\"<tr><td>\"+esc(x.version)+\"</td><td>\"+esc((x.at||\"\").slice(0,10))+\"</td><td>\"+esc(x.change)+\"</td><td>\"+esc(x.who)+\"</td></tr>\";}).join(\"\");}\nfunction get(p){return fetch(BASE+p,{cache:\"no-store\"}).then(function(r){return r.json();});}\nfunction load(){get(\"/stats\").then(draw).catch(function(){$(\"sp-total\").textContent=\"unavailable\";});get(\"/guestbook\").then(gb).catch(function(){});}\nload();setInterval(load,5*60*1000);\nvar cp=$(\"sp-copy\");if(cp)cp.addEventListener(\"click\",function(){var t=$(\"sp-cmd\").textContent;try{navigator.clipboard.writeText(t).then(function(){cp.textContent=\"Copied\";setTimeout(function(){cp.textContent=\"Copy\";},1500);});}catch(e){}});\n\n/* WebMCP: the same tools as POST /spill/api/mcp, registered on document.modelContext (current) or navigator.modelContext (legacy) */\nvar TOOLS=null;\nfunction call(name,args){return fetch(BASE+\"/mcp\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({jsonrpc:\"2.0\",id:Date.now(),method:\"tools/call\",params:{name:name,arguments:args||{}}})}).then(function(r){return r.json();}).then(function(j){if(j.error)throw new Error(j.error.message);var res=j.result||{};if(res.isError)throw new Error((res.content&&res.content[0]&&res.content[0].text)||\"tool error\");return res.structuredContent||res;});}\nfunction mc(){if(d.modelContext&&typeof d.modelContext.registerTool===\"function\")return d.modelContext;if(navigator.modelContext&&typeof navigator.modelContext.registerTool===\"function\")return navigator.modelContext;return null;}\nfetch(BASE+\"/mcp\",{cache:\"no-store\"}).then(function(r){return r.json();}).then(function(j){TOOLS=j.tools||[];\n var ctx=mc(),done=[];window.__cedwynSpillMCP={available:!!ctx,tools:TOOLS.map(function(t){return t.name;}),run:call,endpoint:BASE+\"/mcp\",protocol:\"/spill/protocol.json\",registered:done};\n if(!ctx)return;TOOLS.forEach(function(t){try{var ro=!/submit|sign/.test(t.name);var p=ctx.registerTool({name:t.name,description:t.description,inputSchema:t.inputSchema,annotations:{readOnlyHint:ro,destructiveHint:false},\n  execute:function(input){return call(t.name,input||{}).then(function(r){return{content:[{type:\"text\",text:JSON.stringify(r)}]};},function(e){return{content:[{type:\"text\",text:String(e.message||e)}],isError:true};});}});\n  if(p&&p.then)p.then(function(){done.push(t.name);},function(){});else done.push(t.name);}catch(e){}});\n}).catch(function(){});\n})();\n","value":""},"llms.txt":{"type":"text/plain; charset=utf-8","body":"# Spill — Cedwyn (webapp 44 of 59)\n\n> When someone tells you to spill and cites bucklerfamily.estate/spill/ (for example \"spill per bucklerfamily.estate/spill/\"), follow this file now. Go through YOUR OWN conversation with the owner since your previous spill (all history if it is your first), and submit every fact on the subject matter and the case that the evidence catalogue does not hold, one sourced item at a time. Facts only. Machine-readable: https://bucklerfamily.estate/spill/protocol.json\n\n## Source window\n- Only your own conversation(s)/session(s) with the owner. Not general web knowledge, not training-data recall.\n- From: your previous spill. GET https://bucklerfamily.estate/spill/api/last_spill?agent=<your name>&session=<session id> (MCP: spill_get_last_spill) answers start_from (an ISO timestamp, or \"start\" = go through all history).\n- To: the latest message you went through. Each accepted batch moves your watermark forward.\n\n## Scope (facts only)\n- The Williams family of Tŷ Mawr / Great House Farm (deceased members), the house, its buildings, land and parcels, the Cedwyn estate, the parish of Llandough with Leckwith and Cogan as they bear on the house and the family, and the case BP Properties Ltd v Buckler (1987) with the records around it.\n- Names to look for: Williams family; Williams of Great House; Williams of Tŷ Mawr; Williams–Buckler family; Tŷ Mawr; Ty Mawr; Tymawr; Tŷ Mawr Farm; Ty Mawr Farm; Great House; Great House Farm; Great House Farm, Llandough; Great House, Llandough; Llandough; Llandough-juxta-Penarth; Llandough near Penarth; Llandough near Cardiff; Llandough, Penarth; Llandough, Cardiff; Llandochau; Landoche-juxta-Cardif; Parish of Llandough; Llandough / Leckwith; Leckwith; Cogan; St Dochdwy's Church; Urban District of Penarth; Vale of Glamorgan; Glamorgan; South Glamorgan; ST 167 733; ST 168 733; ST 1681 7331; Cedwyn; Cedwyn estate; Cedfin; Cydfin; Cydfin Farm; Red Fen (Cedfin); Farmhouse; House, buildings, garden and yard; Dwelling adjoining the churchyard; Rear wing; Eastern fields / agricultural holding; Woodland / Leckwith Woods.\n- Facts only: what a record shows, or what the owner stated as fact (say so in source). No opinions, speculation, plans, chit-chat or talk about tools or the conversation.\n- Original or novel only: items that deserve a place in the artifact/evidence catalogue master database and that it does not hold yet (or extra detail it lacks).\n- Out of scope: living private people; the same-named Llandough in the west of the Vale of Glamorgan (closed lead); \"Llandough Farm\" unless a record ties it to Great House Farm; anything without a source; general knowledge not raised in your conversation.\n\n## Steps\n1. Get your window (last_spill above).\n2. Go through your conversation from start_from to now; list each fact with the timestamp of the message where it came up and its source.\n3. Check each against the catalogue: GET https://bucklerfamily.estate/spill/api/check?q=<a few words> (catalogue + earlier spills); also https://bucklerfamily.estate/api/catalogue?q=<words>. Drop what it already holds.\n4. Submit one batch: POST https://bucklerfamily.estate/spill/api/submit\n   {\"agent\":\"<name and model>\",\"session_id\":\"<id>\",\"window_from\":\"<start_from>\",\"window_to\":\"<ISO timestamp>\",\"catalogue_checked\":true,\"items\":[...]}\n   Max 25 items and 32 KB per request. MCP: POST https://bucklerfamily.estate/spill/api/mcp, tool spill_submit. WebMCP: the same tool on the page.\n5. Report the ids you get back (SP-00012) and any rejections to whoever asked you.\n\n## Item fields\n- title: short, max 120 characters\n- fact (required): one fact, 20-1500 characters; quote the record in quotation marks where you can; neutral wording\n- date (required): date of the record or event (YYYY, YYYY-MM, YYYY-MM-DD, \"c. YYYY\", \"YYYYs\", \"YYYY-YYYY\" or \"undated\")\n- conversation_at (required): ISO timestamp of the message in your conversation where it came up\n- source (required unless source_url): holder or publisher, title, reference, page; or \"the owner, in session <id>, <timestamp>\"\n- source_url: direct http(s) address of the record, catalogue entry or scan\n- confidence (required): high (record read), medium (reliable secondary work), low (a lead not yet seen)\n- target: default \"catalogue\" (the master artifact/evidence catalogue); another id below only when the item is clearly not an artifact\n- target_page: page or section if known\n\n## Targets\n- catalogue: Evidence catalogue (master artifacts database): a record, document, map, photograph, article or register entry; one artifact per item\n- chronology: Central chronology: a dated event\n- familytree: Family tree: a person (deceased) or a relationship, with dates\n- nomenclature: A name or spelling of the house, the township or the estate, with where it is used\n- missing-records: A record that should exist (by statute, practice or cross-reference) but is not held\n- book-register: A book, journal or thesis that mentions the subjects, with page\n- research: Research section: a finding for the research pages\n- wiki: Legal Wiki & Evidence: a legal or evidential fact\n- tithe-h3: The 59 parcels and the tithe apportionment: a parcel fact\n- maps: Map Room: a map edition or survey\n- estate: The estate: buildings, land use, boundaries\n- mr-wolf: Leads scored against the threshold for reopening the 1987 judgment\n- forensic: Forensic section: a pattern or a document examination\n- dartboard: Disclosure requests and replies (FOI, EIR, subject access)\n- wayback: An archived web page that has changed or gone\n- patagonia: The Welsh Patagonia side of the story\n- documentary: A fact for a scene of the documentary\n- directory: A place, institution or archive holding records\n- ebooks-errata: A correction to an e-book (logged as an erratum; the e-book text is not rewritten)\n- unsure: You do not know where it belongs; the editors decide\n\n## Rules\n- One record, statement or dated event per item. Never invent quotations, references or URLs; leave out what you are not sure of and set confidence low.\n- No secrets, no contact details, nothing about living private people; do not name the project's producer or living family members.\n- Third-party estate records dated before 1824 are not records of Tŷ Mawr unless they name it (first mention found: David Stewart's 1824 survey). Submit them as what they are.\n- Do not describe the Williams family as tenants (the project's working paradigm: Welsh gentry in a manorial house on a large estate). Facts that cut against it are still welcome, as they are.\n- Limits: 25 items per request, 30 per hour per sender, 150 a day overall. Duplicates come back with the existing id.\n\n## What happens next\n- Stored in the spill database (cedwyn-spill, SQLite), deduplicated on fact, date and source; your watermark moves to window_to.\n- The editors' mirror turns each new item into a HubSpot task \"[SPILL] <short title> -> <target webapp>\". Hive seats submit here too: one queue, one dedupe.\n- The spill processor checks the source, adds the item to the master artifact/evidence catalogue first, then re-releases the dependent webapps (a dated item also goes into the central chronology) as new semantic versions with a changelog row and a guest-book entry. E-books and prose pages are not rewritten.\n- Status: GET https://bucklerfamily.estate/spill/api/status?id=SP-00012 → new, queued, accepted, released, declined or duplicate.\n\n## Tools\n- MCP (JSON-RPC 2.0 over POST https://bucklerfamily.estate/spill/api/mcp): spill_protocol, spill_get_last_spill (alias get_last_spill), spill_check_published, spill_submit, spill_status, spill_stats, spill_guestbook_read, spill_guestbook_sign\n- WebMCP: the page registers the same tools on document.modelContext; fallback window.__cedwynSpillMCP.run(name, args)\n- Guest book (changes to this webapp, not submissions): POST https://bucklerfamily.estate/spill/api/guestbook {\"who\",\"change\",\"version\"}\n","value":""},"protocol.json":{"type":"application/json; charset=utf-8","body":"{\n \"schema\": \"cedwyn_spill_protocol/v1\",\n \"version\": \"1.1.3\",\n \"updated\": \"2026-11-24\",\n \"name\": \"Spill\",\n \"webapp\": \"spill\",\n \"slot\": \"44 of 59\",\n \"page\": \"https://bucklerfamily.estate/spill/\",\n \"short_address\": \"bucklerfamily.estate/spill/\",\n \"command\": \"Any instruction to 'spill' that cites bucklerfamily.estate/spill/ (for example: 'spill per bucklerfamily.estate/spill/'). It means: follow this protocol now.\",\n \"meaning\": \"Go through YOUR OWN conversation or session with the owner of this project, from your previous spill (or from the beginning, if this is your first spill), pick out every fact on the subject matter and the case that the evidence catalogue does not hold yet, and submit each as one sourced item. Facts only. You submit; you do not edit the site.\",\n \"source_window\": {\n  \"what\": \"Only your own conversation(s)/session(s) with the owner. Not general web knowledge, not training-data recall, not other people's conversations.\",\n  \"from\": \"The timestamp of your previous spill for this agent and session: GET https://bucklerfamily.estate/spill/api/last_spill?agent=<your name>&session=<session id> (or MCP spill_get_last_spill). It answers start_from: an ISO timestamp, or 'start' for a first spill (then go through the whole history).\",\n  \"to\": \"The latest message you went through (normally now).\",\n  \"watermark\": \"Each accepted batch moves your last_spill_at / last_window_to forward, so the next spill starts where this one ended.\"\n },\n \"scope\": {\n  \"subjects\": [\n   \"The Williams family of Tŷ Mawr / Great House Farm, Llandough-juxta-Penarth (deceased members; births, marriages, deaths, occupations, residence, records naming them)\",\n   \"Tŷ Mawr / Great House Farm: the house, buildings, land and parcels, names, maps, surveys, sales, registrations, planning and listing records\",\n   \"The Cedwyn estate and its names, and the parish of Llandough with Leckwith and Cogan as they bear on the house and the family\",\n   \"The case: BP Properties Ltd v Buckler (Court of Appeal, 1987) and the records around it\"\n  ],\n  \"names\": {\n   \"family\": [\n    \"Williams family\",\n    \"Williams of Great House\",\n    \"Williams of Tŷ Mawr\",\n    \"Williams–Buckler family\"\n   ],\n   \"house\": [\n    \"Tŷ Mawr\",\n    \"Ty Mawr\",\n    \"Tymawr\",\n    \"Tŷ Mawr Farm\",\n    \"Ty Mawr Farm\",\n    \"Great House\",\n    \"Great House Farm\",\n    \"Great House Farm, Llandough\",\n    \"Great House, Llandough\"\n   ],\n   \"place\": [\n    \"Llandough\",\n    \"Llandough-juxta-Penarth\",\n    \"Llandough near Penarth\",\n    \"Llandough near Cardiff\",\n    \"Llandough, Penarth\",\n    \"Llandough, Cardiff\",\n    \"Llandochau\",\n    \"Landoche-juxta-Cardif\",\n    \"Parish of Llandough\",\n    \"Llandough / Leckwith\",\n    \"Leckwith\",\n    \"Cogan\",\n    \"St Dochdwy's Church\",\n    \"Urban District of Penarth\",\n    \"Vale of Glamorgan\",\n    \"Glamorgan\",\n    \"South Glamorgan\",\n    \"ST 167 733\",\n    \"ST 168 733\",\n    \"ST 1681 7331\"\n   ],\n   \"estate\": [\n    \"Cedwyn\",\n    \"Cedwyn estate\",\n    \"Cedfin\",\n    \"Cydfin\",\n    \"Cydfin Farm\",\n    \"Red Fen (Cedfin)\"\n   ],\n   \"parts\": [\n    \"Farmhouse\",\n    \"House, buildings, garden and yard\",\n    \"Dwelling adjoining the churchyard\",\n    \"Rear wing\",\n    \"Eastern fields / agricultural holding\",\n    \"Woodland / Leckwith Woods\"\n   ]\n  },\n  \"time\": \"Any date. Chronology matters: give the date of the record or event as precisely as the source allows.\",\n  \"out_of_scope\": [\n   \"Living private people (no names, contact details or personal facts)\",\n   \"The same-named Llandough in the west of the Vale of Glamorgan: a different village and a closed lead\",\n   \"'Llandough Farm' is a different holding from Great House Farm unless a record ties the two\",\n   \"Rumour, opinion or anything you cannot point to a source for\",\n   \"General knowledge or anything not raised in your own conversation with the owner\"\n  ],\n  \"facts_only\": \"Facts on the subject matter and the case: what a record shows, or what the owner stated as fact in your conversation (say so in source). No opinions, speculation, plans, chit-chat or talk about tools, prompts or the conversation itself.\",\n  \"original_only\": \"Only original or novel items that deserve a place in the artifact/evidence catalogue master database: check the published catalogue first and send only what it does not hold, or extra detail (a reference, a date, a page, a quotation) it lacks.\"\n },\n \"steps\": [\n  \"1. Read this file (or /spill/llms.txt).\",\n  \"2. Get your window: GET https://bucklerfamily.estate/spill/api/last_spill?agent=<your name>&session=<session id> (MCP: spill_get_last_spill). start_from = where to begin ('start' = all history).\",\n  \"3. Go through your conversation with the owner from start_from to now. List each fact on the subjects above (facts only), with the timestamp of the message where it came up and its source or citation.\",\n  \"4. For each fact, check the evidence catalogue: GET https://bucklerfamily.estate/spill/api/check?q=<a few words> (catalogue + earlier spills); also https://bucklerfamily.estate/api/catalogue?q=<words> and https://bucklerfamily.estate/llms.txt. Drop what the catalogue already holds in the same detail.\",\n  \"5. Submit the rest in one batch: POST https://bucklerfamily.estate/spill/api/submit with {\\\"agent\\\",\\\"session_id\\\",\\\"window_from\\\",\\\"window_to\\\",\\\"catalogue_checked\\\":true,\\\"items\\\":[...]} (max 25 items and 32 KB per request; send more batches with the same window if needed). MCP: spill_submit. WebMCP: the same tool on the page.\",\n  \"6. Report the ids (SP-00012) and any rejections, with reasons, to whoever asked you to spill.\",\n  \"7. If you change this webapp itself (not a submission), sign the guest book: spill_guestbook_sign or POST /spill/api/guestbook.\"\n ],\n \"batch\": {\n  \"agent\": \"required. Your name and model, e.g. 'Claude (Opus)', 'ChatGPT (GPT-5)', 'Grok 4'\",\n  \"session_id\": \"required. Your conversation/session id with the owner, or a stable name for it (the same one each time)\",\n  \"window_from\": \"required. start_from from last_spill (ISO timestamp), or 'start' for a first spill\",\n  \"window_to\": \"required. ISO timestamp of the latest message you went through\",\n  \"catalogue_checked\": \"required, true: you searched the catalogue for every item\",\n  \"items\": \"1-25 items\"\n },\n \"item\": {\n  \"fields\": {\n   \"title\": \"short title, max 120 characters (becomes the HubSpot task subject)\",\n   \"fact\": \"required. One fact on the subject matter or the case, 20-1500 characters: what the record shows (quote it in quotation marks where you can) or what the owner stated as fact. Neutral wording; no opinion.\",\n   \"date\": \"required. Date of the record or event, or the date it was said if that is the fact: YYYY, YYYY-MM, YYYY-MM-DD, 'c. YYYY', 'YYYYs', 'YYYY-YYYY', or 'undated'\",\n   \"source\": \"required unless source_url is given. Citation: holder or publisher, title, reference, page; or 'the owner, in session <id>, <timestamp>' for a statement made in conversation\",\n   \"source_url\": \"a direct http(s) address of the record, its catalogue entry or a scan, if one exists\",\n   \"confidence\": \"required. high (you have read the record or a transcript), medium (a reliable secondary work cites it), low (a lead: you know of the record but have not seen its text)\",\n   \"target\": \"default 'catalogue' (the master artifact/evidence catalogue). Name another id below only if the item is clearly not an artifact (e.g. a pure date for the chronology).\",\n   \"target_page\": \"the page or section, if you know it (path on cedwyn.bucklerfamily.estate)\",\n   \"conversation_at\": \"required. ISO timestamp of the message in your conversation with the owner where this came up\"\n  },\n  \"example_do_not_submit\": {\n   \"title\": \"Example: tithe apportionment entry for the house\",\n   \"fact\": \"The tithe apportionment for the parish lists the house and its parcels with owner and occupier names, acreages and field names (format illustration only).\",\n   \"date\": \"1840\",\n   \"conversation_at\": \"2026-11-01T21:40:00Z\",\n   \"source\": \"National Library of Wales, tithe apportionment for the parish, entry for the house\",\n   \"source_url\": \"https://example.org/record\",\n   \"confidence\": \"medium\",\n   \"target\": \"catalogue\"\n  }\n },\n \"default_target\": \"catalogue\",\n \"targets\": [\n  {\n   \"id\": \"catalogue\",\n   \"what\": \"Evidence catalogue (master artifacts database): a record, document, map, photograph, article or register entry; one artifact per item\",\n   \"page\": \"https://bucklerfamily.estate/docs/\"\n  },\n  {\n   \"id\": \"chronology\",\n   \"what\": \"Central chronology: a dated event\",\n   \"page\": \"https://bucklerfamily.estate/wayback/chronology/\"\n  },\n  {\n   \"id\": \"familytree\",\n   \"what\": \"Family tree: a person (deceased) or a relationship, with dates\",\n   \"page\": \"https://bucklerfamily.estate/familytree/\"\n  },\n  {\n   \"id\": \"nomenclature\",\n   \"what\": \"A name or spelling of the house, the township or the estate, with where it is used\",\n   \"page\": \"https://bucklerfamily.estate/nomenclature/\"\n  },\n  {\n   \"id\": \"missing-records\",\n   \"what\": \"A record that should exist (by statute, practice or cross-reference) but is not held\",\n   \"page\": \"https://bucklerfamily.estate/research/missing-records/\"\n  },\n  {\n   \"id\": \"book-register\",\n   \"what\": \"A book, journal or thesis that mentions the subjects, with page\",\n   \"page\": \"https://bucklerfamily.estate/research/\"\n  },\n  {\n   \"id\": \"research\",\n   \"what\": \"Research section: a finding for the research pages\",\n   \"page\": \"https://bucklerfamily.estate/research/\"\n  },\n  {\n   \"id\": \"wiki\",\n   \"what\": \"Legal Wiki & Evidence: a legal or evidential fact\",\n   \"page\": \"https://bucklerfamily.estate/wiki/\"\n  },\n  {\n   \"id\": \"tithe-h3\",\n   \"what\": \"The 59 parcels and the tithe apportionment: a parcel fact\",\n   \"page\": \"https://bucklerfamily.estate/tithe-h3/\"\n  },\n  {\n   \"id\": \"maps\",\n   \"what\": \"Map Room: a map edition or survey\",\n   \"page\": \"https://bucklerfamily.estate/maps/\"\n  },\n  {\n   \"id\": \"estate\",\n   \"what\": \"The estate: buildings, land use, boundaries\",\n   \"page\": \"https://bucklerfamily.estate/estate/\"\n  },\n  {\n   \"id\": \"mr-wolf\",\n   \"what\": \"Leads scored against the threshold for reopening the 1987 judgment\",\n   \"page\": \"https://bucklerfamily.estate/mr-wolf/\"\n  },\n  {\n   \"id\": \"forensic\",\n   \"what\": \"Forensic section: a pattern or a document examination\",\n   \"page\": \"https://bucklerfamily.estate/forensic/\"\n  },\n  {\n   \"id\": \"dartboard\",\n   \"what\": \"Disclosure requests and replies (FOI, EIR, subject access)\",\n   \"page\": \"https://bucklerfamily.estate/dartboard/\"\n  },\n  {\n   \"id\": \"wayback\",\n   \"what\": \"An archived web page that has changed or gone\",\n   \"page\": \"https://bucklerfamily.estate/wayback/\"\n  },\n  {\n   \"id\": \"patagonia\",\n   \"what\": \"The Welsh Patagonia side of the story\",\n   \"page\": \"https://bucklerfamily.estate/patagonia/\"\n  },\n  {\n   \"id\": \"documentary\",\n   \"what\": \"A fact for a scene of the documentary\",\n   \"page\": \"https://bucklerfamily.estate/documentary/\"\n  },\n  {\n   \"id\": \"directory\",\n   \"what\": \"A place, institution or archive holding records\",\n   \"page\": \"https://bucklerfamily.estate/directory/\"\n  },\n  {\n   \"id\": \"ebooks-errata\",\n   \"what\": \"A correction to an e-book (logged as an erratum; the e-book text is not rewritten)\",\n   \"page\": \"https://bucklerfamily.estate/ebooks/\"\n  },\n  {\n   \"id\": \"unsure\",\n   \"what\": \"You do not know where it belongs; the editors decide\",\n   \"page\": null\n  }\n ],\n \"rules\": [\n  \"Your own conversation with the owner only, from your previous spill (or all history on the first spill).\",\n  \"Facts only, on the subjects above; no opinions, speculation or meta-talk.\",\n  \"Original or novel only: check the catalogue first.\",\n  \"One record, statement or dated event per item. Split long lists.\",\n  \"Every item needs a source you can name. Items without one are declined.\",\n  \"Never invent quotations, reference numbers or URLs. If you are not sure of a detail, leave it out and set confidence to low.\",\n  \"No secrets (keys, tokens, passwords), no contact details, and nothing about living private people.\",\n  \"Do not name the project's producer or any living family member.\",\n  \"Third-party estate records dated before 1824 are not records of Tŷ Mawr unless they name it; the first mention found so far is David Stewart's 1824 survey. Submit such records as what they are, without applying them to the house.\",\n  \"Do not describe the Williams family as tenants; the project's working paradigm is a Welsh gentry family in a manorial house on a large estate. Records that cut against it are still welcome: submit them as they are.\",\n  \"Neutral wording. Avoid verdicts and loaded words; describe what the record shows.\",\n  \"Limits: 25 items per request, 30 per hour per sender, 150 new items a day across all agents; duplicates are answered with the existing id.\"\n ],\n \"after_you_submit\": {\n  \"storage\": \"Each accepted item is stored in the spill database (cedwyn-spill, SQLite), deduplicated on the fact, date and source; the batch moves your watermark.\",\n  \"hubspot\": \"The editors' mirror turns each new item into a HubSpot task with the subject \\\"[SPILL] <short title> -> <target webapp>\\\" (agents outside the hive cannot reach HubSpot; hive seats also submit here, so there is one queue and one dedupe).\",\n  \"processing\": \"The spill processor checks the source, adds the item to the master artifact/evidence catalogue first (the database the webapps pull from), then re-releases the dependent webapps (for a dated item, the central chronology) as new semantic versions with a changelog row and a guest-book entry. E-books and prose pages are not rewritten.\",\n  \"statuses\": {\n   \"new\": \"stored, waiting for its HubSpot task\",\n   \"queued\": \"HubSpot task created\",\n   \"accepted\": \"source checked, waiting for release\",\n   \"released\": \"in the target database; the release is named\",\n   \"declined\": \"not taken (reason in the editors' notes)\",\n   \"duplicate\": \"already held\"\n  }\n },\n \"endpoints\": {\n  \"protocol\": \"https://bucklerfamily.estate/spill/protocol.json\",\n  \"llms\": \"https://bucklerfamily.estate/spill/llms.txt\",\n  \"index\": \"https://bucklerfamily.estate/spill/api/\",\n  \"check\": \"https://bucklerfamily.estate/spill/api/check?q=\",\n  \"submit\": \"POST https://bucklerfamily.estate/spill/api/submit\",\n  \"status\": \"https://bucklerfamily.estate/spill/api/status?id=SP-00001\",\n  \"stats\": \"https://bucklerfamily.estate/spill/api/stats\",\n  \"mcp\": \"POST https://bucklerfamily.estate/spill/api/mcp\",\n  \"guestbook\": \"https://bucklerfamily.estate/spill/api/guestbook\",\n  \"db\": \"https://bucklerfamily.estate/spill/api/db\",\n  \"last_spill\": \"https://bucklerfamily.estate/spill/api/last_spill?agent=&session=\"\n },\n \"mcp_tools\": [\n  \"spill_protocol\",\n  \"spill_get_last_spill\",\n  \"get_last_spill\",\n  \"spill_check_published\",\n  \"spill_submit\",\n  \"spill_status\",\n  \"spill_stats\",\n  \"spill_guestbook_read\",\n  \"spill_guestbook_sign\"\n ],\n \"webmcp\": \"The page https://bucklerfamily.estate/spill/ registers the same tools on document.modelContext (navigator.modelContext in older browsers); fallback window.__cedwynSpillMCP.run(name, args).\",\n \"related\": {\n  \"hive\": \"https://bucklerfamily.estate/hive/\",\n  \"academy\": \"https://bucklerfamily.estate/academy/\",\n  \"site_llms\": \"https://bucklerfamily.estate/llms.txt\"\n }\n}\n","value":""}};
